package com.farcast.agent.darkalgorithm

import android.content.Context
import com.farcast.agent.darkalgorithm.features.MomentFinderService
import com.farcast.agent.darkalgorithm.plugins.PluginAwarePipeline
import com.farcast.agent.darkalgorithm.plugins.PluginRegistry
import kotlinx.coroutines.CoroutineScope
import java.io.File

/**
 * The single entry point a "Feed JSON" button calls. Hands it any CaseFile
 * JSON — generated by CaseFileBuilder, hand-written, or exported from a
 * previous run — and it:
 *  1. imports it (DarkMixer.importCase — already built, this doesn't change it)
 *  2. reads targetProfile to decide which built-in branches actually apply
 *     (no point running DomainRdapSource on a case with no domain)
 *  3. merges in every enabled plugin's declarative source / scorer weights
 *     (PluginAwarePipeline — this is the "adapts to plugins" behavior)
 *  4. wires YoloHydrator so any lead carrying an image gets auto-labeled
 *  5. starts DarkMixer's continuous background worker
 *
 * This is genuinely "autonomous" in the sense Section 3.D asked for:
 * once fed, it re-runs on its own timer without further input, spawning
 * child leads (branch expansion) and writing Evidence as it goes. It is NOT
 * autonomous in the sense of ignoring SafetyGate or the authorized-scope
 * check — those still run on every single pass, same as always.
 */
class DarkAlgorithmController(
    private val context: Context,
    private val pluginRegistry: PluginRegistry,
    private val momentFinder: MomentFinderService,
    private val imageCacheDir: File,
    private val searxngInstanceUrl: String? = null
) {

    /** Returns the running DarkMixer so the caller can stop() it later (e.g.
     *  a "pause case" button) — feeding JSON doesn't mean losing control of it. */
    suspend fun feedJsonAndRun(
        jsonText: String,
        scope: CoroutineScope,
        onProgress: (DarkMixer.ProgressEvent) -> Unit = {}
    ): Pair<CaseFile, DarkMixer> {
        val caseFile = DarkMixer.importCase(jsonText)
        val profile = caseFile.targetProfile

        val builtIns = buildList {
            profile?.domain?.let { add(DomainRdapSource(context, it)) }
            profile?.usernames?.forEach { add(PersonaUsernameSource(context, it)) }
            profile?.ips?.forEach { add(IpThreatSource(context, it)) }
            profile?.freeTextQuery?.let { add(SearchBranchSource(context, it, searxngInstanceUrl)) }
            // Live-data branches (aviation/orbital/quakes/iss/cams/opsec-mirror) aren't
            // target-specific, so they're opt-in via a separate flag, not auto-included
            // just because a case exists — see includeLiveFeeds below if that's wanted.
        }

        val queryParam = profile?.domain ?: profile?.usernames?.firstOrNull() ?: profile?.freeTextQuery.orEmpty()
        // Re-assembled fresh on every pass (see DarkMixer's sourcesProvider) —
        // installing or removing a plugin between two ticks of the SAME
        // running worker takes effect on the next one, no restart needed.
        val sourcesProvider: suspend () -> List<LeadSource> = {
            PluginAwarePipeline.assembleSources(context, pluginRegistry, builtIns, queryParam)
        }
        // Weights are re-read fresh too, for the same reason — a
        // SCORING_WEIGHTS plugin shouldn't need a restart either. NOTE: this
        // re-queries the plugin registry once PER LEAD (LeadScorer.score is
        // called per-lead), not once per pass — fine at this app's scale
        // (a handful of leads per pass, a fast local Room read), but if a
        // case ever has hundreds of leads per pass this is the spot to add a
        // short-lived cache rather than something to discover as a slowdown later.
        val scorer = LeadScorer { lead, scoreCtx ->
            val weights = PluginAwarePipeline.assembleScorerWeights(pluginRegistry, DefaultPhoenixLite.weights)
            PhoenixLite(DefaultPhoenixLite.estimators, weights).score(lead, scoreCtx)
        }
        val yoloHydrator = YoloHydrator(context, momentFinder, imageCacheDir)

        val mixer = DarkMixer(
            sources = emptyList(),              // ignored once sourcesProvider is supplied — see DarkMixer.kt
            sourcesProvider = sourcesProvider,
            hydrators = listOf(yoloHydrator),
            scorer = scorer,
            onProgress = onProgress
        )
        mixer.startWorker(scope, caseFile)
        return caseFile to mixer
    }

    /** Optional: include the always-on live-data branches too, for callers
     *  that want the full allBranchSources() set layered on top of the
     *  target-derived ones rather than just the target-specific subset.
     *  Simpler convenience method — doesn't use sourcesProvider, so unlike
     *  feedJsonAndRun() a plugin installed mid-run here needs a restart to
     *  take effect. Use feedJsonAndRun() if live plugin reload matters more
     *  than having live feeds on by default. */
    suspend fun feedJsonAndRunWithLiveFeeds(jsonText: String, scope: CoroutineScope): Pair<CaseFile, DarkMixer> {
        val caseFile = DarkMixer.importCase(jsonText)
        val profile = caseFile.targetProfile
        val targetSources = buildList {
            profile?.domain?.let { add(DomainRdapSource(context, it)) }
            profile?.usernames?.forEach { add(PersonaUsernameSource(context, it)) }
            profile?.ips?.forEach { add(IpThreatSource(context, it)) }
            profile?.freeTextQuery?.let { add(SearchBranchSource(context, it, searxngInstanceUrl)) }
        }
        val allSources = PluginAwarePipeline.assembleSources(
            context, pluginRegistry, targetSources + allBranchSources(context), profile?.domain.orEmpty()
        )
        val mixer = DarkMixer(sources = allSources, hydrators = listOf(YoloHydrator(context, momentFinder, imageCacheDir)))
        mixer.startWorker(scope, caseFile)
        return caseFile to mixer
    }
}
